return ['domain'=>'zinn-chat','plural-forms'=>'nplurals=3; plural=(((((n == 1)) && ((0 == 0))) || (((n == 0)) && ((((0 == 0)) == 0)))) ? 0 : (((n == 2)) && ((0 == 0))) ? 1 : 2);','language'=>'he_IL','project-id-version'=>'zinn-chat','pot-creation-date'=>'2026-09-13T00:42:26+00:00','po-revision-date'=>'2026-09-13T00:42:26+00:00','x-generator'=>'scripts/wp-i18n-translate.py','messages'=>['Zinn® Chat'=>'Zinn® Chat','https://zinndigital.com/wordpress-plugins/zinn-chat'=>'https://zinndigital.com/wordpress-plugins/zinn-chat','A fast, privacy-respecting live chat for your website. Answers visitors with AI when you are busy, hands them to you when they need a person, and emails you anything you miss. Under 10 KB on the page and no requests at all until somebody opens it.'=>'צ\'אט חי מהיר המכבד את הפרטיות לאתר שלך. עונה למבקרים באמצעות בינה מלאכותית כשאתה עסוק, מעביר אותם אליך כשהם זקוקים לנציג אנושי, ושולח לך במייל כל מה שפספסת. שוקל פחות מ-10 KB בעמוד וללא בקשות כלל עד שמישהו פותח אותו.','Neil Lock — CEO, Zinn Digital® Ltd'=>'Neil Lock — CEO, Zinn Digital® Ltd','https://zinndigital.com'=>'https://zinndigital.com','Settings'=>'הגדרות','That does not look like a Zinn® Chat key. Copy it from the Live chat page of your Zinn Digital® dashboard — it starts with zc_.'=>'זה אינו נראה כמו מפתח Zinn® Chat. העתק אותו ממיקוד הצ\'אט החי בלוח הבקרה שלך ב-Zinn Digital® — הוא מתחיל ב-zc_.','Add your chat key before switching the chat on — without it there is nothing for the widget to connect to.'=>'הוסף את מפתח הצ\'אט שלך לפני הפעלת הצ\'אט — בלעדיו אין ווידג\'ט שיוכל להתחבר אליו.','Live chat for this site. Visitors get an answer straight away, you get anything you miss by email, and the whole thing is under 10 KB on the page.'=>'צ\'אט חי עבור אתר זה. מבקרים מקבלים מענה מיד, אתם מקבלים כל פנייה שפספסתם בדוא"ל, והדבר כולו שוקל פחות מ-10 קילו-בייט בעמוד.','The chat is live on this site.'=>'הצ\'אט פעיל באתר זה.','The chat is switched off. Nothing is loaded on your site.'=>'הצ\'אט כבוי. שום דבר אינו נטען באתר שלך.','Chat key'=>'מפתח צ\'אט','Copy this from the Live chat page of your %s.'=>'העתק זאת מדף ה-Live chat של ה-%s שלך.','Zinn Digital® dashboard'=>'לוח הבקרה של Zinn Digital®','Show the chat'=>'הצג את הצ\'אט','Show the chat window to visitors of this site'=>'הצג את חלון הצ\'אט למבקרים באתר זה','Until you tick this, the plugin adds nothing at all to your pages — no script, no cookie, no requests.'=>'עד שתסמן תיבה זו, התוסף אינו מוסיף דבר לעמודים שלך — לא סקריפט, לא קוקי, לא בקשות.','%s — guides and services'=>'%s — מדריכים ושירותים','User guides'=>'מדריכי משתמש','Read the %s user guide'=>'קרא את מדריך המשתמש %s','Hide this'=>'הסתר את זה','Zinn® hosting for WordPress'=>'אחסון Zinn® עבור WordPress','LiteSpeed, daily backups, free migration and a control panel built for people who run more than one site.'=>'LiteSpeed, גיבויים יומיים, העברה חינם ולוח בקרה המותאם לאנשים המנהלים יותר מאתר אחד.','The Zinn® marketplace'=>'החנות של Zinn®','Buy and sell established sites, domains and link placements, with the money held safely until both sides are happy.'=>'קנו ומכרו אתרים מבוססים, דומיינים ומיקומי קישורים, כאשר הכסף מוחזק בבטחה עד ששני הצדדים מרוצים.','Zinn Hub® — hire people who do this for a living'=>'Zinn Hub® — שים אנשים שעושים את זה למחייתם','Our global freelance marketplace: browse over 10,000 ready-made services from writers, designers, developers and SEOs, or post a project and let them bid.'=>'השוק הגלובלי שלנו לפרילנסרים: עיינו בלמעלה מ-10,000 שירותים מוכנים מראש מכותבים, מעצבים, מפתחים ואנשי קידום אתרים (SEO), או פרסמו פרויקט ותנו להם להגיש הצעות.','See the Zinn Digital® release notes.'=>'עיין בהערות השחרור של Zinn Digital®.','The downloaded update failed its integrity check and was not installed.'=>'עדכון שהורד נכשל בבדיקת תקינות ולא הותקן.']];